// Burn-in export: record the player's canvas until the clip ends.
export async function recordClip(video, recorder) {
  recorder.start();
  video.play();
  await new Promise((resolve) => {
    const check = () => {
      if (video.currentTime >= video.duration - 0.05) resolve();
      else requestAnimationFrame(check);
    };
    check();
  });
  recorder.stop();
  return recorder.result();
}
